#[path="/Users/chazu/dev/zig/birnam/rust/birnam-siphon/tests/support/mod.rs"] mod support;
use support::*;
use birnam_abi::{Oop,borrowed_slice,id_protocol::{Operand,Outcome,Protocol,NativeEntry}};
use std::{cell::{Cell,RefCell},ffi::c_void,os::unix::ffi::OsStrExt,time::Instant};
struct Probe { id:Protocol,gc:Oop, trace:Oop, nodes:Vec<Oop>, edges:Vec<(usize,usize)>, count:Cell<usize>, previous:Cell<usize>, collections:Cell<usize>, charge:Cell<usize>, observing:Cell<bool>, original_roots:NativeEntry, start:Instant, phases:RefCell<Vec<(String,f64,usize,usize)>>, complete_ms:Cell<f64> }
unsafe extern "C" fn gc_roots(c:*mut c_void,r:Oop,a:*const Operand,n:usize)->Outcome {
 let p=unsafe{&*c.cast::<Probe>()};
 if unsafe{borrowed_slice(a,n)}.unwrap()[0].as_object()==Some(p.gc) {p.collections.set(p.collections.get()+1);let v=unsafe{p.id.send_named(p.gc,b"allocationBytes",&[])}.unwrap().as_word().unwrap();p.charge.set(p.charge.get()+v);}
 unsafe{(p.original_roots.method.unwrap())(p.original_roots.context,r,a,n)}
}
unsafe extern "C" fn phase(c:*mut c_void,_:Oop,a:*const Operand,n:usize)->Outcome {
 let p=unsafe{&*c.cast::<Probe>()};let [tag]=unsafe{borrowed_slice(a,n)}.unwrap() else{panic!("phase")};
 let raw=unsafe{send(p.id,p.id.receiver,b"symbolBytesOf:",&[*tag])}.as_bytes().unwrap();
 let name=String::from_utf8_lossy(unsafe{birnam_abi::borrowed_bytes(raw.pointer,raw.length)}.unwrap()).into_owned();
 let bytes=unsafe{send(p.id,p.gc,b"allocationBytes",&[])}.as_word().unwrap();
 p.phases.borrow_mut().push((name,p.start.elapsed().as_secs_f64(),p.collections.get(),p.charge.get()+bytes));
 Outcome::loaded(Operand::object(p.trace))
}
unsafe extern "C" fn observe(c:*mut c_void,r:Oop,a:*const Operand,n:usize)->Outcome {
 let p=unsafe{&*c.cast::<Probe>()};let [sink]=unsafe{borrowed_slice(a,n)}.unwrap() else{panic!("observe")};let sink=object(*sink);
 (||unsafe{
 if p.nodes.is_empty() {p.observing.set(true);let result=p.id.send_named(r,b"originalObserve:",&[Operand::object(sink)]);p.observing.set(false);return result;}
 for (i,&o) in p.nodes.iter().enumerate(){p.id.send_named(sink,b"allocation:bytes:identity:",&[Operand::object(o),Operand::word(0),Operand::word(i+1)])?;}
 p.id.send_named(sink,b"root:",&[Operand::object(p.nodes[0])])?;
 for &(f,t) in &p.edges {p.id.send_named(sink,b"edgeFrom:to:",&[Operand::object(p.nodes[f]),Operand::object(p.nodes[t])])?;}
 p.id.send_named(sink,b"complete:",&[Operand::word(1)])
 })().map_or_else(|e|e,Outcome::loaded)
}
unsafe fn row(c:*mut c_void,a:*const Operand,n:usize,reached:bool)->Outcome {
 let p=unsafe{&*c.cast::<Probe>()};let [o,identity]=unsafe{borrowed_slice(a,n)}.unwrap() else{panic!("row")};let i=identity.as_word().unwrap();assert!(i>p.previous.replace(i));p.count.set(p.count.get()+1);
 if !p.nodes.is_empty(){assert_eq!(object(*o),p.nodes[i-1]);assert_eq!(reached,i<=p.nodes.len()/2);}
 Outcome::loaded(Operand::unit())
}
unsafe extern "C" fn yes(c:*mut c_void,_:Oop,a:*const Operand,n:usize)->Outcome {unsafe{row(c,a,n,true)}}
unsafe extern "C" fn no(c:*mut c_void,_:Oop,a:*const Operand,n:usize)->Outcome {unsafe{row(c,a,n,false)}}
unsafe extern "C" fn complete(c:*mut c_void,_:Oop,_:*const Operand,_:usize)->Outcome {
 let p=unsafe{&*c.cast::<Probe>()};let now=Instant::now();p.observing.set(false);unsafe{collect(p.id,p.gc)};p.complete_ms.set(now.elapsed().as_secs_f64()*1000.);Outcome::loaded(Operand::word(73))
}
fn main(){unsafe{
 let count:usize=std::env::args().nth(1).unwrap().parse().unwrap();let budget:usize=std::env::args().nth(2).unwrap().parse().unwrap();
 let id=id();let ns=load(id,"bootstrap",&[Operand::bytes(directory().as_os_str().as_bytes())]);
 let named=|n:&[u8]|object(send(id,ns,b"at:",&[Operand::object(id.intern_name(n).unwrap())]));let roots=named(b"Roots");let gc=named(b"GC");send(id,gc,b"precisePayloads:",&[Operand::word(1)]);
 let mut nodes=Vec::new();let vt=behavior(id);let hold=retain(id,roots,vt);
 for _ in 0..count {let o=allocate(id,vt,0);retain(id,roots,o);nodes.push(o);}
 let mut edges=Vec::new();for i in 0..count {let half=count/2;let base=(i/half)*half;for step in [1,2,3,7]{edges.push((i,base+(i+step)%half));}}
 let gcvt=object(send(id,id.receiver,b"behaviorOf:",&[Operand::object(gc)]));
 let original=send(id,id.receiver,b"bind:to:",&[Operand::object(id.intern_name(b"rootsDo:").unwrap()),Operand::object(gc)]).as_entry().unwrap();
 let p=Box::leak(Box::new(Probe{id,gc,trace:named(b"Trace"),nodes,edges,count:Cell::new(0),previous:Cell::new(0),collections:Cell::new(0),charge:Cell::new(0),observing:Cell::new(false),original_roots:original,start:Instant::now(),phases:RefCell::new(vec![]),complete_ms:Cell::new(0.)}));let c=(p as *mut Probe).cast();
 install(id,gcvt,b"rootsDo:",gc_roots,c);
 let perfvt=behavior(id);install(id,perfvt,b"phase:",phase,c);let perf=allocate(id,perfvt,0);retain(id,roots,perf);send(id,ns,b"at:put:",&[Operand::object(id.intern_name(b"TracePerf").unwrap()),Operand::object(perf)]);
 let storage=named(b"Storage");let svt=object(send(id,id.receiver,b"behaviorOf:",&[Operand::object(storage)]));let orig=send(id,id.receiver,b"bindingOf:in:",&[Operand::object(id.intern_name(b"observe:").unwrap()),Operand::object(svt)]);send(id,svt,b"addMethod",&[Operand::object(id.intern_name(b"originalObserve:").unwrap()),orig]);install(id,svt,b"observe:",observe,c);
 let rvt=behavior(id);install(id,rvt,b"reached:identity:",yes,c);install(id,rvt,b"notReached:identity:",no,c);install(id,rvt,b"complete:",complete,c);let visitor=allocate(id,rvt,0);retain(id,roots,visitor);
 collect(id,gc);p.collections.set(0);p.charge.set(0);
 if budget==0 {send(id,gc,b"automaticCollection:",&[Operand::word(0)]);} else {send(id,gc,b"budget:",&[Operand::word(budget)]);}
 p.start=Instant::now();let result=send(id,p.trace,b"report:acceptingGaps:",&[Operand::object(visitor),Operand::word(usize::MAX)]);assert_eq!(result.as_word(),Some(73));
 let elapsed=p.start.elapsed().as_secs_f64();let tail=send(id,gc,b"allocationBytes",&[]).as_word().unwrap();
 println!("RESULT nodes={} rows={} budget={} seconds={:.6} gc={} charge={} completion_ms={:.3}",count,p.count.get(),budget,elapsed,p.collections.get(),p.charge.get()+tail,p.complete_ms.get());
 for (name,sec,gcs,bytes) in p.phases.borrow().iter(){println!("PHASE {} {:.6} {} {}",name,sec,gcs,bytes);}
 release(id,roots,hold);
}}

